def transform(grid):
    """Extend the vertical lines implied by the holes in horizontal bars."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find columns where horizontal stripes contain a one-cell hole.
    tracks = set()
    for row in grid:
        for c in range(1, w - 1):
            if row[c] == 0 and row[c - 1] and row[c + 1]:
                tracks.add(c)

    for c in tracks:
        crossings = [
            (r, grid[r][c - 1])
            for r in range(h)
            if grid[r][c] == 0 and grid[r][c - 1] and grid[r][c + 1]
        ]
        markers = [(r, grid[r][c]) for r in range(h) if grid[r][c] != 0]

        # Each crossing extends its stripe's color upward, stopping at the
        # previous crossing or an existing vertical marker.
        for i, (r, color) in enumerate(crossings):
            start = crossings[i - 1][0] + 1 if i else 0
            for rr in range(start, r + 1):
                if grid[rr][c] == 0 or rr == r:
                    out[rr][c] = color

        # A lower isolated vertical marker continues to the bottom edge.
        if markers:
            mr, marker_color = markers[-1]
            if crossings and mr > crossings[-1][0]:
                for rr in range(crossings[-1][0] + 1, h):
                    out[rr][c] = marker_color

    return out
